// Generated by `just generate` from `src/plugins/dotclaude/slices/spec/adapters/runs.ts`. Edit the source and run `just generate`.
// `dotclaude-spec runs`: prints the number of agent runs that a wave of `/ship` may start now.

import { RATE_LIMITS_FILE } from "../../../kernel/paths.ts";
import { capOf, parseSample, runsAllowed, type UsageSample } from "../domain/runs.ts";
import type { Run } from "./run.ts";

/** The usage sample of the project, or null when the status line has kept none. A file that is not a sample throws. */
const sampleOf = async (run: Run): Promise<UsageSample | null> => {
  const text = await run.store.files.read(RATE_LIMITS_FILE);
  return text === null ? null : parseSample(text);
};

/** Prints the runs of one wave, from the cap of `CLAUDE_CODE_MAX_CONCURRENT_SUBAGENTS` and the usage sample. */
export const runsCommand = async (run: Run): Promise<number> => {
  const cap = capOf(process.env["CLAUDE_CODE_MAX_CONCURRENT_SUBAGENTS"]);
  const allowed = runsAllowed(
    cap,
    await sampleOf(run),
    run.clock.now().getTime(),
  );
  run.io.log(String(allowed));
  return 0;
};
